/** Shared helpers for page metadata: robots, Open Graph and absolute URLs. */
import type { Metadata } from "next";

import { routing } from "@/i18n/routing";
import { allowIndexing, portalName, siteUrl } from "@/lib/config";

/** Generated by app/og-default.png/route.tsx; used when a page has no photo of its own. */
export const DEFAULT_OG_IMAGE = { url: "/og-default.png", width: 1200, height: 630 };

/**
 * Robots tag for a page. Nothing is indexable unless SEO_ALLOW_INDEXING=true, so local and
 * staging copies of the site never end up in Google.
 * Always set `robots` with this helper: `robots: undefined` would wipe the layout's value.
 */
export function robotsFor(indexable: boolean): NonNullable<Metadata["robots"]> {
  if (!allowIndexing) return { index: false, follow: false };
  return indexable ? { index: true, follow: true } : { index: false, follow: true };
}

export function ogLocale(locale: string): string {
  return locale === "ar" ? "ar_SA" : "en_SA";
}

type OgImage = { url: string; width: number; height: number };

/**
 * A page's openGraph block. Next.js replaces (does not merge) the layout's openGraph, so
 * every page that sets one goes through here to keep siteName and the fallback image.
 */
export function openGraph(
  locale: string,
  page: { title: string; description?: string; url: string; image?: OgImage | null },
): NonNullable<Metadata["openGraph"]> {
  return {
    type: "website",
    siteName: portalName,
    locale: ogLocale(locale),
    title: page.title,
    description: page.description,
    url: page.url,
    images: [page.image ?? DEFAULT_OG_IMAGE],
  };
}

/** hreflang map for paths that differ per locale, plus x-default (Arabic). */
export function languageAlternates(pathFor: (locale: "ar" | "en") => string) {
  const languages: Record<string, string> = Object.fromEntries(
    routing.locales.map((l) => [l, pathFor(l)]),
  );
  languages["x-default"] = pathFor(routing.defaultLocale);
  return languages;
}

/** Absolute URL for JSON-LD and sitemaps, with Arabic segments percent-encoded. */
export function absoluteUrl(path: string): string {
  return `${siteUrl}${encodeURI(path)}`;
}

/** Safe to put inside <script type="application/ld+json">. */
export function jsonLdHtml(data: unknown): { __html: string } {
  return { __html: JSON.stringify(data).replace(/</g, "\\u003c") };
}
